import torch from torch import nn from torch.nn import functional as F
class Attention(nn.Module): def __init__(self, width, heads): super().__init__() assert width % heads == 0 self.heads = heads self.qkv = nn.Linear(width, 3 * width) self.proj = nn.Linear(width, width)
def forward(self, x): b, t, c = x.shape q, k, v = self.qkv(x).chunk(3, dim=-1) q, k, v = [z.reshape(b, t, self.heads, c // self.heads) .transpose(1, 2) for z in (q, k, v)] score = q @ k.transpose(-2, -1) / (c // self.heads) ** 0.5 mask = torch.ones(t, t, device=x.device, dtype=torch.bool).tril() score = score.masked_fill(~mask, float("-inf")) weights = score.float().softmax(dim=-1).to(v.dtype) out = (weights @ v).transpose(1, 2).contiguous().reshape(b, t, c) return self.proj(out)
class Block(nn.Module): def __init__(self, width, heads): super().__init__() self.ln1, self.ln2 = nn.LayerNorm(width), nn.LayerNorm(width) self.attn = Attention(width, heads) self.ff = nn.Sequential(nn.Linear(width, 4 * width), nn.GELU(), nn.Linear(4 * width, width))
def forward(self, x): x = x + self.attn(self.ln1(x)) return x + self.ff(self.ln2(x))
class MiniGPT(nn.Module): def __init__(self, vocab=8192, width=384, heads=6, layers=6, context=512): super().__init__() self.context = context self.token = nn.Embedding(vocab, width) self.pos = nn.Embedding(context, width) self.blocks = nn.Sequential(*[Block(width, heads) for _ in range(layers)]) self.norm = nn.LayerNorm(width) self.head = nn.Linear(width, vocab, bias=False) self.apply(self._init) self.head.weight = self.token.weight
@staticmethod def _init(m): if isinstance(m, (nn.Linear, nn.Embedding)): nn.init.normal_(m.weight, std=0.02) if isinstance(m, nn.Linear) and m.bias is not None: nn.init.zeros_(m.bias)
def forward(self, ids, targets=None): _, t = ids.shape assert t <= self.context x = self.token(ids) + self.pos(torch.arange(t, device=ids.device)) logits = self.head(self.norm(self.blocks(x))) loss = None if targets is None else F.cross_entropy( logits.float().reshape(-1, logits.size(-1)), targets.reshape(-1)) return logits, loss

