import re
from decimal import Decimal

NUMBER = re.compile(r"[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?")

def number(text):
    s = text.strip()
    return Decimal(s.replace(",", "")) if NUMBER.fullmatch(s) else None

def final_answer(text):
    lines = text.strip().splitlines()
    if not lines or not lines[-1].startswith("Answer:"):
        return None
    if sum(line.startswith("Answer:") for line in lines) != 1:
        return None
    return number(lines[-1].split(":", 1)[1])

def correctness_reward(completions, answer, **kwargs):
    if len(completions) != len(answer):
        raise ValueError("候选与答案数量不一致")
    result = []
    for completion, target in zip(completions, answer):
        text = (completion[0]["content"] if isinstance(completion, list)
                else completion)
        predicted, expected = final_answer(text), number(target)
        result.append(float(predicted is not None and expected is not None
                            and predicted == expected))
    return result

if __name__ == "__main__":
    assert final_answer("Explanation.\nAnswer: 72.0") == number("72")
    assert final_answer("Answer: 1,200") == number("1200")
    assert final_answer("Answer: -3") == number("-3")
    for bad in ["72", "Answer: 1,2", "Answer: NaN", "Answer: 1/2",
                "Answer: 1\nAnswer: 2", "Answer: 2\nmore text"]:
        assert final_answer(bad) is None
    assert correctness_reward(["Answer: 72", "Answer: 71"], ["72", "72"]) == [1.0, 0.0]
    print("verifier examples OK")

def repair_task(task, generate, run_public, judge_hidden, max_attempts=3):
    messages = [
        {"role": "system", "content": "Fix the function. Return only Python code."},
        {"role": "user", "content": task["prompt"]}]
    trace, candidate = [], None
    for attempt in range(max_attempts):
        candidate = generate(messages, max_new_tokens=512)
        observation = run_public(candidate, task["public_tests"])
        trace.append({"attempt": attempt + 1, "code": candidate,
                      "observation": observation})
        if observation["status"] == "infra_error":
            return {"status": "infra_error", "trace": trace}
        if observation["status"] == "passed_public":
            break
        messages.extend([
            {"role": "assistant", "content": candidate},
            {"role": "user", "content": observation["summary"][:2000]}])
    # 隐藏评分只在提交最终候选后执行，不作为继续重试的反馈。
    final = judge_hidden(candidate, task["hidden_tests"])
    return {"status": final["status"], "trace": trace}
